DO $do$ DECLARE workbench_id BIGINT; resource_id BIGINT; studio_id BIGINT; modeling_id BIGINT; warehouse_planning_id BIGINT; standards_id BIGINT; dimensional_modeling_id BIGINT; data_metrics_id BIGINT; data_studio_id BIGINT; ops_center_id BIGINT; governance_id BIGINT; assets_id BIGINT; consumption_id BIGINT; services_id BIGINT; bi_apps_id BIGINT; bi_id BIGINT; BEGIN SELECT id INTO workbench_id FROM portal_menu WHERE deleted = FALSE AND parent_id IS NULL AND (name = 'sys.nav.portal.workbench' OR metadata LIKE '%"key":"workbench"%') ORDER BY id LIMIT 1;
SELECT id INTO resource_id FROM portal_menu WHERE deleted = FALSE AND parent_id IS NULL AND (name IN ('sys.nav.portal.resourceCenter', 'sys.nav.portal.dataIntegration') OR metadata LIKE '%"key":"resource"%') ORDER BY id LIMIT 1;
SELECT id INTO studio_id FROM portal_menu WHERE deleted = FALSE AND parent_id IS NULL AND (name = 'sys.nav.portal.studioCenter' OR metadata LIKE '%"key":"studio"%') ORDER BY id LIMIT 1;
