SELECT id INTO consumption_id FROM portal_menu WHERE deleted = FALSE AND (name = 'sys.nav.portal.dataConsumption' OR metadata LIKE '%"key":"consumption"%') ORDER BY CASE WHEN parent_id IS NULL THEN 0 ELSE 1 END, id LIMIT 1;
IF studio_id IS NULL THEN INSERT INTO portal_menu ( name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted, created_by, created_date, last_modified_by, last_modified_date ) VALUES ( 'sys.nav.portal.studioCenter', 'studio', NULL, 3, '{"key":"studio","sectionKey":"studio","titleKey":"sys.nav.portal.studioCenter","title":"数据开发与运维","icon":"solar:code-bold-duotone"}', NULL, 'solar:code-bold-duotone', 'GENERAL', FALSE, 'system', now(), 'system', now() ) RETURNING id INTO studio_id; END IF;
IF governance_id IS NULL THEN INSERT INTO portal_menu ( name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted, created_by, created_date, last_modified_by, last_modified_date ) VALUES ( 'sys.nav.portal.governanceOperations', 'governance', NULL, 4, '{"key":"governance","sectionKey":"governance","titleKey":"sys.nav.portal.governanceOperations","title":"数据治理","icon":"solar:shield-check-bold-duotone"}', NULL, 'solar:shield-check-bold-duotone', 'GENERAL', FALSE, 'system', now(), 'system', now() ) RETURNING id INTO governance_id; END IF;
