IF warehouse_planning_id IS NULL THEN INSERT INTO portal_menu ( name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted, created_by, created_date, last_modified_by, last_modified_date ) VALUES ( 'sys.nav.portal.warehousePlanning', 'studio/modeling/warehouse-planning', NULL, 1, '{"key":"warehouse-planning","sectionKey":"studio","entryKey":"warehouse-planning","titleKey":"sys.nav.portal.warehousePlanning","title":"数仓规划","icon":"solar:map-point-bold-duotone"}', modeling_id, 'solar:map-point-bold-duotone', 'GENERAL', FALSE, 'system', now(), 'system', now() ) RETURNING id INTO warehouse_planning_id; ELSE UPDATE portal_menu SET parent_id = modeling_id, name = 'sys.nav.portal.warehousePlanning', path = 'studio/modeling/warehouse-planning', sort_order = 1, metadata = '{"key":"warehouse-planning","sectionKey":"studio","entryKey":"warehouse-planning","titleKey":"sys.nav.portal.warehousePlanning","title":"数仓规划","icon":"solar:map-point-bold-duotone"}', icon = 'solar:map-point-bold-duotone', component = NULL, deleted = FALSE, last_modified_by = 'system', last_modified_date = now() WHERE id = warehouse_planning_id; END IF;
