IF standards_id IS NULL THEN INSERT INTO portal_menu ( name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted, created_by, created_date, last_modified_by, last_modified_date ) VALUES ( 'sys.nav.portal.dataStandards', 'studio/modeling/standards', NULL, 2, '{"key":"standards","sectionKey":"studio","entryKey":"standards","titleKey":"sys.nav.portal.dataStandards","title":"数据标准","icon":"solar:document-text-bold-duotone"}', modeling_id, 'solar:document-text-bold-duotone', 'GENERAL', FALSE, 'system', now(), 'system', now() ) RETURNING id INTO standards_id; ELSE UPDATE portal_menu SET parent_id = modeling_id, name = 'sys.nav.portal.dataStandards', path = 'studio/modeling/standards', sort_order = 2, metadata = '{"key":"standards","sectionKey":"studio","entryKey":"standards","titleKey":"sys.nav.portal.dataStandards","title":"数据标准","icon":"solar:document-text-bold-duotone"}', icon = 'solar:document-text-bold-duotone', component = NULL, deleted = FALSE, last_modified_by = 'system', last_modified_date = now() WHERE id = standards_id; END IF;
