IF dimensional_modeling_id IS NULL THEN INSERT INTO portal_menu ( name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted, created_by, created_date, last_modified_by, last_modified_date ) VALUES ( 'sys.nav.portal.dimensionalModeling', 'studio/modeling/dimensional-modeling', NULL, 3, '{"key":"dimensional-modeling","sectionKey":"studio","entryKey":"dimensional-modeling","titleKey":"sys.nav.portal.dimensionalModeling","title":"维度建模","icon":"solar:cube-bold-duotone"}', modeling_id, 'solar:cube-bold-duotone', 'GENERAL', FALSE, 'system', now(), 'system', now() ) RETURNING id INTO dimensional_modeling_id; ELSE UPDATE portal_menu SET parent_id = modeling_id, path = 'studio/modeling/dimensional-modeling', sort_order = 3, metadata = '{"key":"dimensional-modeling","sectionKey":"studio","entryKey":"dimensional-modeling","titleKey":"sys.nav.portal.dimensionalModeling","title":"维度建模","icon":"solar:cube-bold-duotone"}', icon = 'solar:cube-bold-duotone', component = NULL, deleted = FALSE, last_modified_by = 'system', last_modified_date = now() WHERE id = dimensional_modeling_id; END IF;
SELECT id INTO data_metrics_id FROM portal_menu WHERE deleted = FALSE AND ( name = 'sys.nav.portal.studioMetricModeling' OR name = 'sys.nav.portal.dataMetrics' OR metadata LIKE '%"titleKey":"sys.nav.portal.studioMetricModeling"%' OR metadata LIKE '%"titleKey":"sys.nav.portal.dataMetrics"%' OR metadata LIKE '%"key":"metric-modeling"%' OR metadata LIKE '%"key":"data-metrics"%' ) ORDER BY CASE WHEN parent_id IS NULL THEN 0 ELSE 1 END, id LIMIT 1;
IF data_metrics_id IS NULL THEN INSERT INTO portal_menu ( name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted, created_by, created_date, last_modified_by, last_modified_date ) VALUES ( 'sys.nav.portal.dataMetrics', 'studio/modeling/data-metrics', NULL, 4, '{"key":"data-metrics","sectionKey":"studio","entryKey":"data-metrics","titleKey":"sys.nav.portal.dataMetrics","title":"数据指标","icon":"solar:graph-bold-duotone"}', modeling_id, 'solar:graph-bold-duotone', 'GENERAL', FALSE, 'system', now(), 'system', now() ) RETURNING id INTO data_metrics_id; ELSE UPDATE portal_menu SET parent_id = modeling_id, name = 'sys.nav.portal.dataMetrics', path = 'studio/modeling/data-metrics', sort_order = 4, metadata = '{"key":"data-metrics","sectionKey":"studio","entryKey":"data-metrics","titleKey":"sys.nav.portal.dataMetrics","title":"数据指标","icon":"solar:graph-bold-duotone"}', icon = 'solar:graph-bold-duotone', component = NULL, deleted = FALSE, last_modified_by = 'system', last_modified_date = now() WHERE id = data_metrics_id; END IF;
