IF ops_center_id IS NULL THEN INSERT INTO portal_menu ( name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted, created_by, created_date, last_modified_by, last_modified_date ) VALUES ( 'sys.nav.portal.studioOpsCenter', 'studio/ops-center', NULL, 3, '{"key":"ops-center","sectionKey":"studio","entryKey":"ops-center","titleKey":"sys.nav.portal.studioOpsCenter","title":"运维中心","icon":"solar:settings-bold-duotone"}', studio_id, 'solar:settings-bold-duotone', 'GENERAL', FALSE, 'system', now(), 'system', now() ) RETURNING id INTO ops_center_id; ELSE UPDATE portal_menu SET parent_id = studio_id, name = 'sys.nav.portal.studioOpsCenter', path = 'studio/ops-center', sort_order = 3, metadata = '{"key":"ops-center","sectionKey":"studio","entryKey":"ops-center","titleKey":"sys.nav.portal.studioOpsCenter","title":"运维中心","icon":"solar:settings-bold-duotone"}', icon = 'solar:settings-bold-duotone', component = NULL, deleted = FALSE, last_modified_by = 'system', last_modified_date = now() WHERE id = ops_center_id; END IF;
SELECT id INTO assets_id FROM portal_menu WHERE deleted = FALSE AND ( name = 'sys.nav.portal.dataPortal' OR name = 'sys.nav.portal.governanceAssets' OR metadata LIKE '%"key":"portal"%' OR metadata LIKE '%"key":"assets"%' ) ORDER BY CASE WHEN parent_id IS NULL THEN 0 ELSE 1 END, id LIMIT 1;
IF assets_id IS NULL THEN INSERT INTO portal_menu ( name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted, created_by, created_date, last_modified_by, last_modified_date ) VALUES ( 'sys.nav.portal.governanceAssets', 'governance/assets', NULL, 1, '{"key":"assets","sectionKey":"governance","entryKey":"assets","titleKey":"sys.nav.portal.governanceAssets","title":"数据地图与资产","icon":"solar:book-bold-duotone"}', governance_id, 'solar:book-bold-duotone', 'GENERAL', FALSE, 'system', now(), 'system', now() ) RETURNING id INTO assets_id; ELSE UPDATE portal_menu SET parent_id = governance_id, name = 'sys.nav.portal.governanceAssets', path = 'governance/assets', sort_order = 1, metadata = '{"key":"assets","sectionKey":"governance","entryKey":"assets","titleKey":"sys.nav.portal.governanceAssets","title":"数据地图与资产","icon":"solar:book-bold-duotone"}', icon = 'solar:book-bold-duotone', component = NULL, deleted = FALSE, last_modified_by = 'system', last_modified_date = now() WHERE id = assets_id; END IF;
