UPDATE portal_menu SET parent_id = standards_id, path = CASE WHEN name = 'sys.nav.portal.governanceStandardPackage' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceStandardPackage"%' THEN 'studio/modeling/standards/standard-package' WHEN name = 'sys.nav.portal.governanceGlossary' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceGlossary"%' THEN 'studio/modeling/standards/glossary' WHEN name = 'sys.nav.portal.governanceElements' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceElements"%' THEN 'studio/modeling/standards/elements' WHEN name = 'sys.nav.portal.governanceReference' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceReference"%' THEN 'studio/modeling/standards/reference' WHEN name = 'sys.nav.portal.governanceTemplates' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceTemplates"%' THEN 'studio/modeling/standards/templates' ELSE path END, sort_order = CASE WHEN name = 'sys.nav.portal.governanceStandardPackage' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceStandardPackage"%' THEN 1 WHEN name = 'sys.nav.portal.governanceGlossary' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceGlossary"%' THEN 2 WHEN name = 'sys.nav.portal.governanceElements' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceElements"%' THEN 3 WHEN name = 'sys.nav.portal.governanceReference' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceReference"%' THEN 4 WHEN name = 'sys.nav.portal.governanceTemplates' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceTemplates"%' THEN 5 ELSE sort_order END, metadata = CASE WHEN name = 'sys.nav.portal.governanceStandardPackage' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceStandardPackage"%' THEN '{"key":"standard-package","sectionKey":"studio","entryKey":"standard-package","titleKey":"sys.nav.portal.governanceStandardPackage","title":"标准包导入","icon":"solar:import-bold-duotone","externalLink":"/foundation/standard-package"}' WHEN name = 'sys.nav.portal.governanceGlossary' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceGlossary"%' THEN '{"key":"glossary","sectionKey":"studio","entryKey":"glossary","titleKey":"sys.nav.portal.governanceGlossary","title":"业务术语","icon":"solar:book-bold-duotone","externalLink":"/governance/standards/glossary"}' WHEN name = 'sys.nav.portal.governanceElements' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceElements"%' THEN '{"key":"elements","sectionKey":"studio","entryKey":"elements","titleKey":"sys.nav.portal.governanceElements","title":"数据元","icon":"solar:document-bold-duotone","externalLink":"/governance/standards/elements"}' WHEN name = 'sys.nav.portal.governanceReference' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceReference"%' THEN '{"key":"reference","sectionKey":"studio","entryKey":"reference","titleKey":"sys.nav.portal.governanceReference","title":"公共码表","icon":"solar:database-bold-duotone","externalLink":"/governance/standards/reference"}' WHEN name = 'sys.nav.portal.governanceTemplates' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceTemplates"%' THEN '{"key":"templates","sectionKey":"studio","entryKey":"templates","titleKey":"sys.nav.portal.governanceTemplates","title":"标准模板","icon":"solar:folder-with-files-bold-duotone","externalLink":"/governance/templates"}' ELSE metadata END, component = NULL, deleted = FALSE, last_modified_by = 'system', last_modified_date = now() WHERE deleted = FALSE AND ( name IN ( 'sys.nav.portal.governanceStandardPackage', 'sys.nav.portal.governanceGlossary', 'sys.nav.portal.governanceElements', 'sys.nav.portal.governanceReference', 'sys.nav.portal.governanceTemplates' ) OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceStandardPackage"%' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceGlossary"%' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceElements"%' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceReference"%' OR metadata LIKE '%"titleKey":"sys.nav.portal.governanceTemplates"%' );
UPDATE portal_menu SET parent_id = dimensional_modeling_id, path = CASE WHEN name = 'sys.nav.portal.studioLowCodeDevelopment' OR metadata LIKE '%"titleKey":"sys.nav.portal.studioLowCodeDevelopment"%' THEN 'studio/modeling/dimensional-modeling/low-code-development' WHEN name = 'sys.nav.portal.studioSqlModeling' OR metadata LIKE '%"titleKey":"sys.nav.portal.studioSqlModeling"%' THEN 'studio/modeling/dimensional-modeling/sql-modeling' WHEN name = 'sys.nav.portal.studioSemanticObjects' OR metadata LIKE '%"titleKey":"sys.nav.portal.studioSemanticObjects"%' THEN 'studio/modeling/dimensional-modeling/objects' WHEN name = 'sys.nav.portal.studioSemanticModels' OR metadata LIKE '%"titleKey":"sys.nav.portal.studioSemanticModels"%' THEN 'studio/modeling/dimensional-modeling/models' WHEN name = 'sys.nav.portal.studioDbtFiles' OR metadata LIKE '%"titleKey":"sys.nav.portal.studioDbtFiles"%' THEN 'studio/modeling/dimensional-modeling/dbt-files' ELSE path END, sort_order = CASE WHEN name = 'sys.nav.portal.studioLowCodeDevelopment' OR metadata LIKE '%"titleKey":"sys.nav.portal.studioLowCodeDevelopment"%' THEN 1 WHEN name = 'sys.nav.portal.studioSqlModeling' OR metadata LIKE '%"titleKey":"sys.nav.portal.studioSqlModeling"%' THEN 2 WHEN name = 'sys.nav.portal.studioSemanticObjects' OR metadata LIKE '%"titleKey":"sys.nav.portal.studioSemanticObjects"%' THEN 3 WHEN name = 'sys.nav.portal.studioSemanticModels' OR metadata LIKE '%"titleKey":"sys.nav.portal.studioSemanticModels"%' THEN 4 WHEN name = 'sys.nav.portal.studioDbtFiles' OR metadata LIKE '%"titleKey":"sys.nav.portal.studioDbtFiles"%' THEN 5 ELSE sort_order END, component = NULL, deleted = FALSE, last_modified_by = 'system', last_modified_date = now() WHERE deleted = FALSE AND ( name IN ( 'sys.nav.portal.studioLowCodeDevelopment', 'sys.nav.portal.studioSqlModeling', 'sys.nav.portal.studioSemanticObjects', 'sys.nav.portal.studioSemanticModels', 'sys.nav.portal.studioDbtFiles' ) OR metadata LIKE '%"titleKey":"sys.nav.portal.studioLow